function setTheme(theme){themeMode=theme;document.documentElement.dataset.theme=theme;document.body.dataset.theme=theme;document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#101216':'#f6f7f9';document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===theme)));try{localStorage.setItem('button-study-theme',theme)}catch{}document.querySelector('#status').textContent=(theme==='dark'?'Dark':'Light')+' materials'}
document.querySelectorAll('[data-theme-choice]').forEach(b=>{b.innerHTML=icon(b.dataset.themeChoice==='light'?'sun':'moon')+b.textContent;b.addEventListener('click',()=>setTheme(b.dataset.themeChoice))});setTheme(themeMode);
