const QUALITY={"2": {"score": 8.6, "note": "Convincing glass edge, lavender plus tile, and split-button balance."}, "3": {"score": 8.5, "note": "Original purple surface with crisp pinpoints and delicate moving hairlines."}, "4": {"score": 8.8, "note": "Precise metallic hairline, moving reflections, and a clean white face."}, "7": {"score": 8.6, "note": "Sharp dot matrix, electric lime inset, and seamless expanding hover."}, "8": {"score": 8.8, "note": "Soft transmitted color, frosted highlights, and translucent lettering."}, "9": {"score": 8.3, "note": "Balanced primary pair with clean spacing and a precise lavender inset rim."}, "10": {"score": 8.4, "note": "Coherent soft depth, cool gray embossing, and a recessed arrow."}, "11": {"score": 9.0, "note": "Glossy inflated blue surface, continuous hover morphing, and a soft press response."}, "14": {"score": 9.1, "note": "Recessed mechanical rocker, molded plastic bevels, opposing pivot states, and inset indicator."}, "16": {"score": 10.0, "note": "Reference-faithful forest-glass capsule, convex lens with hairline refraction, attached sprout filaments and pinpoints, and synchronized spring switch. Reviewed in both themes at 100%, 200%, and 300%."}, "18": {"score": 9.1, "note": "Continuous sculpted keycaps, filtered rubber grain, spring travel, and functional airflow/heat particles. Strict visual review; 10/10 remains the target."}};
